            if grid[r][c] != bg:
                pts.setdefault(grid[r][c], []).append((r, c))

    # Extend each marked stroke outward from its exposed end.
    for color, p in pts.items():
        if len(p) == 1:
            r, c = p[0]
            # A singleton on the lower-left side of the pattern continues outward.
            dr, dc = 1, -1
        else:
            (r1, c1), (r2, c2) = p[0], p[1]
            dr, dc = r2-r1, c2-c1
            import math
            g = math.gcd(abs(dr), abs(dc))
            dr, dc = dr//g, dc//g

            # Continue from the endpoint furthest toward the appropriate boundary.
            ends = [(r1, c1, -dr, -dc), (r2, c2, dr, dc)]
            r, c, sr, sc = min(ends, key=lambda e: (e[0]+e[1], e[0]))
            if color == 1:
