            r += sr
            c += sc
            while 0 <= r < h and 0 <= c < w:
                if out[r][c] == bg:
                    out[r][c] = color
                r += sr
                c += sc
            continue

        r += dr
        c += dc
        while 0 <= r < h and 0 <= c < w:
            if out[r][c] == bg:
                out[r][c] = color
            r += dr
